"""Exact parsing and formatting of monetary amounts.

Amounts are represented as :class:`~decimal.Decimal` values with an
exponent of ``-2``, i.e. whole cents.  No operation in this module relies
on the caller's decimal context, so amounts stay exact even when the
global precision is too low to represent them.
"""

import re
from decimal import Context, Decimal

#: Largest amount accepted by :func:`parse_amount`.
MAX_AMOUNT = Decimal("1000000.00")

#: Largest accepted amount expressed as an integer number of cents.
MAX_AMOUNT_CENTS = 100000000

_CENT = Decimal("0.01")

#: Strings must match this ASCII grammar in full:
#: ``[+-]?[0-9]+(?:\.[0-9]+)?``.
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)

#: Quantizing to cents needs at most 9 significant digits for any accepted
#: amount (1000000.00 -> 100000000 cents).  The explicit context keeps the
#: result independent of the caller's precision, rounding and traps.
_QUANTIZE_CONTEXT = Context(prec=28)


def _coerce_to_decimal(value):
    """Convert a supported input to a Decimal without using any context."""
    if isinstance(value, bool):
        raise ValueError("amount must not be a bool")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, str):
        if _AMOUNT_RE.fullmatch(value) is None:
            raise ValueError(
                "amount string must match [+-]?[0-9]+(?:\\.[0-9]+)?"
            )
        return Decimal(value)
    raise ValueError("amount must be a Decimal, an int or a string")


def _is_cent_exact(amount):
    """Return True if ``amount`` is a whole number of cents."""
    _, digits, exponent = amount.as_tuple()
    if exponent >= -2:
        return True
    extra = -exponent - 2
    return not any(digits[-extra:])


def _validate_amount(amount):
    if not amount.is_finite():
        raise ValueError("amount must be finite")
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > MAX_AMOUNT:
        raise ValueError("amount must not exceed 1000000.00")
    if not _is_cent_exact(amount):
        raise ValueError("amount must be exactly representable in cents")


def parse_amount(value):
    """Parse and validate a monetary amount, returning a Decimal in cents.

    Accepts Decimal objects, ints (excluding bool) and strings that fully
    match ``[+-]?[0-9]+(?:\\.[0-9]+)?``.  The value must be positive, at
    most ``1000000.00`` and exactly representable in cents; otherwise a
    :class:`ValueError` is raised.  The result always has exponent ``-2``.
    """
    amount = _coerce_to_decimal(value)
    _validate_amount(amount)
    return amount.quantize(_CENT, context=_QUANTIZE_CONTEXT)


def format_amount(value):
    return format(value, ".2f")
EOF
