"""Invoice helpers built on exact decimal arithmetic."""

from decimal import Decimal

from .money import MAX_AMOUNT_CENTS, format_amount, parse_amount


def _cents(amount):
    """Return the integer number of cents of a validated amount."""
    # parse_amount guarantees a positive Decimal with exponent -2.
    return int("".join(map(str, amount.as_tuple().digits)))


def make_invoice(amounts):
    """Return the exact total of ``amounts`` as a two-decimal string.

    ``amounts`` must be a Python list; every item goes through
    :func:`~src.money.parse_amount` and the sum must not exceed
    ``1000000.00``.  Summation is done on integers, so it stays exact
    regardless of the caller's decimal precision.
    """
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")

    total_cents = 0
    for item in amounts:
        total_cents += _cents(parse_amount(item))

    if total_cents > MAX_AMOUNT_CENTS:
        raise ValueError("total must not exceed 1000000.00")

    total = Decimal((0, tuple(int(digit) for digit in str(total_cents)), -2))
    return {"total": format_amount(total), "count": len(amounts)}
