import decimal, random
from decimal import Decimal
from fractions import Fraction
from src.money import parse_amount
from src.api import make_invoice

random.seed(1234)
ctx = decimal.getcontext()

def rand_amount_str():
    whole = random.randint(0, 1000000)
    frac = random.randint(0, 99)
    if whole == 0 and frac == 0:
        whole = 1
    s = f"{whole}.{frac:02d}"
    if random.random() < 0.3:
        s += "0" * random.randint(1, 4)
    if random.random() < 0.2:
        s = "0" * random.randint(1, 3) + s
    if random.random() < 0.15:
        s = "+" + s
    return s

for trial in range(2000):
    prec = random.choice([1, 2, 3, 4, 5, 9, 28, 50])
    ctx.prec = prec
    old_flags = ctx.flags.copy()
    n = random.randint(0, 8)
    items, expected = [], Fraction(0)
    for _ in range(n):
        s = rand_amount_str()
        v = parse_amount(s)
        f = Fraction(s.replace("+", ""))
        assert Fraction(v) == f, (s, v, f)
        assert v.as_tuple().exponent == -2
        assert Decimal(0) < v <= Decimal("1000000.00")
        items.append(s)
        expected += f
    if expected > 1000000:
        try:
            make_invoice(items)
        except ValueError:
            pass
        else:
            raise AssertionError("expected overflow %r" % (items,))
    else:
        inv = make_invoice(items)
        assert inv["count"] == n
        assert Fraction(inv["total"]) == expected, (items, inv, expected)
    assert ctx.prec == prec
    assert ctx.flags == old_flags, (ctx.flags, old_flags)

bad_tokens = [".1", "1.", "1e2", "1_0", " 1", "1 ", "١٢.٣", "1.234", "0",
              "-1.00", "1000000.01", "", ".", "+.", "1..2"]
for s in bad_tokens:
    try:
        parse_amount(s)
    except ValueError:
        pass
    else:
        raise AssertionError("accepted %r" % s)

# boundary stress with list of repeated items under precision 3
ctx.prec = 3
assert make_invoice(["1.00"] * 1000000) == {"total": "1000000.00", "count": 1000000}
try:
    make_invoice(["1.00"] * 1000001)
except ValueError:
    pass
else:
    raise AssertionError("expected ValueError over max")
ctx.prec = 28
print("randomized property checks passed")
